const x=$input.first().json||{};
const oge=String(x.oge||'').toUpperCase();
const permission=String(x.requested_permission||'READ').toUpperCase();
const idempotency=String(x.idempotency_key||'').trim();
const invalid=!idempotency||!['READ','WRITE','EXECUTE','DANGEROUS'].includes(permission);
let lane='unsupported';let role='NO_ROUTE';
if(['OGE-6','OGE-57'].includes(oge)){lane='task_event';role='NORMALIZE_AND_ROUTE_ONLY';}
else if(oge==='OGE-27'){lane='browser_postrun';role='EVIDENCE_ONLY';}
else if(oge==='OGE-28'){lane='codex_postrun';role='EVIDENCE_ONLY';}
else if(oge==='OGE-43'){lane='github_evidence';role='AGGREGATE_ONLY';}
else if(['OGE-58','OGE-59','OGE-60'].includes(oge)){lane='provider_composition';role='COMPOSE_AFTER_YELLOW_ONLY';}
const approvalRequired=['WRITE','EXECUTE','DANGEROUS'].includes(permission);
return [{json:{schema:'OGENIC_N8N_TASK_ROUTE_V1',ok:!invalid&&lane!=='unsupported',task_id:String(x.task_id||'').slice(0,180),oge,capability_id:String(x.capability_id||'').slice(0,180),lane,n8n_role:role,requested_permission:permission,approval_required:approvalRequired,yellow_authorization_required:true,execution_allowed:false,reason:invalid?'INVALID_TASK_ENVELOPE':lane==='unsupported'?'OGE_NOT_PLACED_IN_N8N':'ROUTE_PREPARED_YELLOW_DECISION_REQUIRED',idempotency_key:idempotency.slice(0,240)}}];
